	render := app.buildRender(80)
	var joined strings.Builder
	for _, line := range render.lines {
		for _, seg := range line.segments {
			joined.WriteString(seg.text)
		}
		joined.WriteByte('\n')
	}

	if !strings.Contains(joined.String(), `"z"`) {
		t.Fatalf("expanded table cell did not render nested object:\n%s", joined.String())
	}
}

