func getNode(root any, p path) (any, bool) {
	current := root
	for _, part := range p {
		switch v := current.(type) {
		case []any:
			if part.isKey || part.index < 0 || part.index >= len(v) {
				return nil, false
			}
			current = v[part.index]
		case map[string]any:
			if !part.isKey {
				return nil, false
			}
			child, ok := v[part.key]
			if !ok {
				return nil, false
			}
			current = child
		default:
			return nil, false
		}
	}
	return current, true
}

