	return out
}

func appendPathKey(p path, key string) path {
	out := clonePath(p)
	out = append(out, pathPart{isKey: true, key: key})
	return out
}

func clonePath(p path) path {
	out := make(path, len(p))
	copy(out, p)
	return out
}

func pathsEqual(a, b path) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func clamp(value, low, high int) int {
	if value < low {
		return low
	}
	if value > high {
		return high
	}
	return value
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

